#include "tigersheets/ooxml.hpp"
#include <pugixml.hpp>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <unistd.h>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{char pattern[]="/tmp/tigersheets-validation-XXXXXX";const auto* directory=mkdtemp(pattern);require(directory,"temporary validation directory");const auto path=(std::filesystem::path(directory)/"validation.xlsx").string();auto book=WorkbookSession().snapshot();book["sheets"].push_back({{"id","input"},{"name","Input"},{"cells",Json::array({{{"row",3},{"col",2},{"input","0.1"}}})}});const Json rule={{"type","list"},{"range",{{"row1",3},{"col1",3},{"row2",3},{"col2",3}}},{"formula1","=Input!$B$3:$B$3"},{"allowBlank",true}};book["sheets"][0]["dataValidations"]=Json::array({rule});writeWorkbook(path,book);auto loaded=readWorkbook(path);require(loaded.workbook.at("sheets")[0].value("dataValidations",Json::array())==Json::array({rule}),"native list data validation must survive XLSX save/reopen");pugi::xml_document doc;require(doc.load_string(loaded.entries.at("xl/worksheets/sheet1.xml").c_str()),"native validation XML parses");const auto validation=doc.child("worksheet").child("dataValidations").child("dataValidation");require(std::string(validation.attribute("type").value())=="list"&&std::string(validation.attribute("sqref").value())=="C3","native list uses SpreadsheetML type and target reference");require(std::string(validation.child("formula1").text().as_string())=="Input!$B$3:$B$3","native source formula excludes the entry equals sign");
 const std::string opaque="<dataValidation type=\"whole\" operator=\"between\" sqref=\"D4\"><formula1>1</formula1><formula2>10</formula2></dataValidation><dataValidation type=\"list\" sqref=\"E4\"><formula1>Missing!A1:A3</formula1></dataValidation>";auto& sheetXml=loaded.entries.at("xl/worksheets/sheet1.xml");sheetXml.insert(sheetXml.find("</dataValidations>"),opaque);auto changed=loaded.workbook;changed["sheets"][0]["dataValidations"][0]["range"]={{"row1",4},{"col1",3},{"row2",4},{"col2",3}};writeWorkbook(path,changed,&loaded);auto reopened=readWorkbook(path);require(reopened.workbook.at("sheets")[0].at("dataValidations").size()==1,"unsupported and unresolved imported validations remain opaque without blocking workbook open");const auto& native=reopened.entries.at("xl/worksheets/sheet1.xml");require(native.find("operator=\"between\"")!=std::string::npos&&native.find("Missing!A1:A3")!=std::string::npos,"editing a managed list preserves unrelated unsupported native validation semantics");auto cleared=reopened.workbook;cleared["sheets"][0].erase("dataValidations");writeWorkbook(path,cleared,&reopened);auto last=readWorkbook(path);require(!last.workbook.at("sheets")[0].contains("dataValidations"),"removing the last managed list removes only managed native rules");require(last.entries.at("xl/worksheets/sheet1.xml").find("Missing!A1:A3")!=std::string::npos,"clearing managed lists retains opaque native rules");
 std::filesystem::remove_all(directory);std::cout<<"worksheet validation OOXML tests passed\n";return 0;}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
